-- ============================================================
-- 花卉识别系统数据库创建脚本（完整版100种花卉）
-- 数据库: flower_recognition
-- 版本: 2.0
-- 创建日期: 2026-01-24
-- ============================================================

-- 1. 创建数据库
CREATE DATABASE IF NOT EXISTS `flower_recognition` DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

USE `flower_recognition`;

-- ============================================================
-- 2. 创建用户表 (users)
-- ============================================================
CREATE TABLE IF NOT EXISTS `users` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '用户ID',
  `openid` VARCHAR(64) NOT NULL COMMENT '微信OpenID',
  `unionid` VARCHAR(64) DEFAULT NULL COMMENT '微信UnionID',
  `nickname` VARCHAR(100) DEFAULT NULL COMMENT '用户昵称',
  `avatar_url` VARCHAR(500) DEFAULT NULL COMMENT '用户头像URL',
  `gender` TINYINT UNSIGNED DEFAULT NULL COMMENT '性别: 0-未知, 1-男, 2-女',
  `country` VARCHAR(50) DEFAULT NULL COMMENT '国家',
  `province` VARCHAR(50) DEFAULT NULL COMMENT '省份',
  `city` VARCHAR(50) DEFAULT NULL COMMENT '城市',
  `language` VARCHAR(20) DEFAULT 'zh_CN' COMMENT '语言',
  `status` TINYINT UNSIGNED DEFAULT 1 COMMENT '状态: 0-禁用, 1-正常',
  `last_login_at` DATETIME DEFAULT NULL COMMENT '最后登录时间',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_openid` (`openid`),
  KEY `idx_unionid` (`unionid`),
  KEY `idx_status` (`status`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户表';

-- ============================================================
-- 3. 创建花卉表 (flowers) - 完整100种花卉数据
-- ============================================================
CREATE TABLE IF NOT EXISTS `flowers` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '花卉ID',
  `class_id` INT UNSIGNED NOT NULL COMMENT '模型类别ID(对应模型输出的索引)',
  `english_name` VARCHAR(100) NOT NULL COMMENT '英文名称',
  `chinese_name` VARCHAR(100) NOT NULL COMMENT '中文名称',
  `scientific_name` VARCHAR(150) NOT NULL COMMENT '学名',
  `family` VARCHAR(50) DEFAULT NULL COMMENT '科名(中文)',
  `family_en` VARCHAR(50) DEFAULT NULL COMMENT '科名(英文)',
  `genus` VARCHAR(50) DEFAULT NULL COMMENT '属名(中文)',
  `genus_en` VARCHAR(50) DEFAULT NULL COMMENT '属名(英文)',
  `habits` TEXT COMMENT '生长习性',
  `description` TEXT COMMENT '详细描述',
  `characteristics` TEXT COMMENT '特征描述',
  `flowering_period` VARCHAR(100) DEFAULT NULL COMMENT '花期',
  `distribution` TEXT COMMENT '分布地区',
  `care_tips` TEXT COMMENT '养护建议',
  `image_url` VARCHAR(500) DEFAULT NULL COMMENT '示例图片URL',
  `status` TINYINT UNSIGNED DEFAULT 1 COMMENT '状态: 0-禁用, 1-启用',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_class_id` (`class_id`),
  KEY `idx_english_name` (`english_name`),
  KEY `idx_chinese_name` (`chinese_name`),
  KEY `idx_scientific_name` (`scientific_name`),
  KEY `idx_family` (`family`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='花卉表';

-- ============================================================
-- 4. 插入100种常见花卉数据
-- ============================================================
INSERT INTO `flowers` (`class_id`, `english_name`, `chinese_name`, `scientific_name`, `family`, `family_en`, `genus`, `genus_en`, `habits`, `description`, `characteristics`, `flowering_period`, `distribution`, `care_tips`) VALUES
-- 0. 庭荠
(0, 'alyssum', '庭荠', 'Lobularia maritima', '十字花科', 'Brassicaceae', '庭荠属', 'Lobularia', '喜阳光充足，耐寒性强，适应性强。喜凉爽气候，不耐高温。适合疏松肥沃、排水良好的土壤。', '庭荠是十字花科庭荠属的多年生草本植物，常作一年生栽培。株高10-30厘米，茎匍匐生长。叶片小而密集，呈灰绿色。总状花序顶生，花小而密集，有白色、粉色、紫色等，花瓣四片呈十字形排列，具有淡淡香气。花期长，可从春季持续到秋季。', '花朵小巧密集，花瓣呈十字形排列，具有香气。植株低矮匍匐，适合做地被植物。', '4-10月', '原产于地中海沿岸，现世界各地广泛栽培', '喜阳光充足，保持土壤湿润但不积水。定期修剪促进分枝和开花。耐寒但怕高温，夏季注意遮阴。'),
-- 1. 苋菜
(1, 'amaranth', '苋菜', 'Amaranthus tricolor', '苋科', 'Amaranthaceae', '苋属', 'Amaranthus', '喜温暖气候，耐热性强，不耐寒。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '苋菜是苋科苋属的一年生草本植物。株高50-150厘米，茎直立，多分枝。叶片卵形或菱形，颜色鲜艳，有红色、紫色、绿色等。穗状花序顶生或腋生，花小而不显著。主要作为蔬菜栽培，嫩叶可食用。部分品种具有观赏价值。', '叶片颜色鲜艳，常用作观赏或食用。适应性强，生长迅速。', '7-10月', '原产于热带美洲，现世界各地广泛栽培', '喜温暖环境，不耐寒。保持土壤湿润。喜阳光充足但也能耐半阴。生长期间可追肥促进生长。'),
-- 2. 银莲花
(2, 'anemone', '银莲花', 'Anemone coronaria', '毛茛科', 'Ranunculaceae', '银莲花属', 'Anemone', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '银莲花是毛茛科银莲花属的多年生草本植物。株高30-60厘米，茎直立。基生叶掌状分裂，茎生叶对生。花单生或数朵生于茎顶，花大而美丽，有红、粉、白、蓝等多种颜色，花瓣6-8枚，花蕊黄色，形似罂粟花。', '花朵大而美丽，色彩丰富。叶片掌状分裂。地下具根茎。', '3-5月', '原产于地中海沿岸地区，中国各地有栽培', '喜半阴环境，避免烈日暴晒。保持土壤湿润但排水良好。冬季耐寒，夏季休眠。定期施肥促进生长。'),
-- 3. 红掌
(3, 'anthurium', '红掌', 'Anthurium andraeanum', '天南星科', 'Araceae', '花烛属', 'Anthurium', '喜温暖湿润环境，适宜温度20-30℃。喜散射光，忌强光直射。要求疏松透气、排水良好的基质。', '红掌是天南星科花烛属的多年生草本植物。叶片心形或卵形，革质，深绿色，有光泽。肉穗花序圆柱形，黄色，周围有红色的佛焰苞，呈心形，色彩鲜艳夺目。花期长，几乎全年可开花，是重要的观赏花卉。', '佛焰苞红色心形，肉穗花序黄色。叶片心形革质。观赏价值高。', '全年', '原产于南美洲热带地区，现世界各地广泛栽培', '保持较高湿度和温度。避免强光直射。定期施肥，以磷钾肥为主。保持通风，预防病虫害。'),
-- 4. 硬果菊
(4, 'arctotis', '硬果菊', 'Arctotis stoechadifolia', '菊科', 'Asteraceae', '硬果菊属', 'Arctotis', '喜阳光充足，耐热性强，耐旱。适应性广，对土壤要求不严。', '硬果菊是菊科硬果菊属的多年生草本植物，常作一年生栽培。株高30-50厘米，茎直立，多分枝。叶片羽状分裂，灰绿色。头状花序单生茎顶，花大，直径可达8厘米，舌状花有黄色、橙色、粉色等，管状花深紫色。花期长，从初夏可持续到秋季。', '花朵大而鲜艳，色彩丰富。叶片灰绿色羽状分裂。喜阳光充足。', '5-10月', '原产于南非，现世界各地广泛栽培', '喜阳光充足，耐旱能力强。土壤要求不严。保持土壤微湿即可。及时摘除残花促进持续开花。'),
-- 5. 紫菀
(5, 'aster', '紫菀', 'Aster novi-belgii', '菊科', 'Asteraceae', '紫菀属', 'Aster', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '紫菀是菊科紫菀属的多年生草本植物。株高50-150厘米，茎直立，多分枝。叶片披针形，互生。头状花序多数，排成伞房状或圆锥状，舌状花蓝紫色或白色，管状花黄色。花期8-11月，是秋季重要的观赏花卉。', '头状花序蓝紫色或白色，形似雏菊。秋季开花，花期长。', '8-11月', '原产于北美洲、欧洲、亚洲，中国各地有分布', '喜凉爽气候，耐寒。保持土壤湿润但排水良好。喜阳光充足。定期分株更新，保持植株活力。'),
-- 6. 杜鹃
(6, 'azalea', '杜鹃', 'Rhododendron simsii', '杜鹃花科', 'Ericaceae', '杜鹃属', 'Rhododendron', '喜凉爽湿润气候，喜酸性土壤。喜半阴，忌强光直射。喜温暖湿润环境，不耐高温。', '杜鹃是杜鹃花科杜鹃属的灌木或小乔木。株高1-3米，分枝多。叶片椭圆形或卵形，革质，常绿或落叶。花2-6朵簇生枝顶，花冠漏斗形，有红、粉、白、紫等多种颜色，有的品种具有斑点或条纹。花期4-6月，是中国传统名花之一。', '花朵色彩丰富，漏斗形花冠。叶片椭圆形革质。是中国十大名花之一。', '4-6月', '原产于中国，现世界各地广泛栽培', '喜酸性土壤，喜半阴。保持土壤湿润但排水良好。喜凉爽气候，夏季需遮阴降温。定期修剪整形。'),
-- 7. 满天星
(7, 'baby_breath', '满天星', 'Gypsophila paniculata', '石竹科', 'Caryophyllaceae', '石头花属', 'Gypsophila', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的碱性土壤。', '满天星是石竹科石头花属的多年生草本植物。株高50-100厘米，茎直立，多分枝呈丛生状。叶片小而狭，粉绿色。圆锥状聚伞花序顶生，花极小而密集，白色或淡粉色，状如繁星点点。花期6-8月，是重要的切花和配花材料。', '花小而密集，状如繁星。叶片粉绿色。常作为切花配材。', '6-8月', '原产于欧洲、亚洲中部，现世界各地广泛栽培', '喜碱性土壤，喜阳光充足。耐寒但怕积水。保持土壤微湿。定期修剪促进分枝。'),
-- 8. 假马齿苋
(8, 'bacopa', '假马齿苋', 'Bacopa monnieri', '车前科', 'Plantaginaceae', '假马齿苋属', 'Bacopa', '喜温暖湿润环境，耐热性强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '假马齿苋是车前科假马齿苋属的多年生草本植物。株高10-30厘米，茎匍匐生长，节上生根。叶片肉质，对生，倒卵形或匙形。腋生花小，单生或数朵簇生，花白色或淡蓝色，有五个花瓣。花期几乎全年。是良好的地被植物和水族箱前景草。', '茎匍匐，节上生根。叶片肉质。小白花或蓝花。常用于水草缸和地被。', '全年', '原产于热带和亚热带地区，现世界各地广泛分布', '喜温暖湿润环境。喜阳光充足。保持土壤湿润。生长迅速，需要定期修剪。'),
-- 9. 凤仙花
(9, 'balsam', '凤仙花', 'Impatiens balsamina', '凤仙花科', 'Balsaminaceae', '凤仙花属', 'Impatiens', '喜温暖湿润气候，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '凤仙花是凤仙花科凤仙花属的一年生草本植物。株高30-80厘米，茎直立，肉质，多汁。叶片互生，披针形。花单生或数朵生于叶腋，花形奇特，有单瓣和重瓣，花色有红、粉、白、紫等多种，花瓣有距，触之即裂。果实为蒴果，成熟时触之即裂。', '花有距，触之即裂。茎肉质多汁。果实成熟自动弹裂传播种子。', '7-10月', '原产于中国、印度、马来西亚，现世界各地广泛栽培', '喜半阴环境，不耐强光。保持土壤湿润但不积水。喜温暖气候，不耐寒。定期施肥促进开花。'),
-- 10. 秋海棠
(10, 'begonia', '秋海棠', 'Begonia semperflorens', '秋海棠科', 'Begoniaceae', '秋海棠属', 'Begonia', '喜温暖湿润环境，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的微酸性土壤。', '秋海棠是秋海棠科秋海棠属的多年生草本植物。株高20-50厘米，茎直立，肉质。叶片卵形或心形，绿色或铜绿色，常有斑纹。聚伞花序腋生，花单性，雌雄同株，花色有红、粉、白等，四季可开花。是重要的观赏花卉。', '叶片常有心形斑纹。茎肉质。花色丰富，四季开花。', '全年', '原产于南美洲，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持较高湿度。喜温暖，不耐寒。避免积水，预防根腐。'),
-- 11. 天堂鸟
(11, 'bird_of_paradise', '天堂鸟', 'Strelitzia reginae', '鹤望兰科', 'Strelitziaceae', '鹤望兰属', 'Strelitzia', '喜温暖湿润气候，耐寒性较弱。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '天堂鸟是鹤望兰科鹤望兰属的多年生草本植物。株高1-2米。叶片大，革质，长圆形，似芭蕉叶，叶柄细长。花序顶生，总花梗长，具大型佛焰苞，橙黄色，内含数朵花，蓝色花瓣和橙色萼片组成鸟状，极富观赏价值。', '花形奇特，似飞翔的鸟。叶片宽大似芭蕉。佛焰苞橙色，花蓝色。', '全年，主要在春夏季', '原产于南非，现世界各地广泛栽培', '需要充足阳光。保持土壤湿润但不积水。喜温暖，冬季注意保温。定期施肥促进生长开花。'),
-- 12. 黑眼苏珊
(12, 'black_eyed_susan', '黑眼苏珊', 'Thunbergia alata', '爵床科', 'Acanthaceae', '翼叶山牵牛属', 'Thunbergia', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '黑眼苏珊是爵床科翼叶山牵牛属的多年生缠绕草本植物，常作一年生栽培。茎蔓生，可达2-3米。叶片心形或卵形，对生。花单生叶腋，花冠漏斗形，黄色或橙色，喉部深紫色或黑色，形成明显的黑眼。花期6-10月。', '花冠黄色或橙色，喉部黑色形成黑眼。茎蔓生。叶片心形。', '6-10月', '原产于非洲热带地区，现世界各地广泛栽培', '需要支架供其攀援。喜阳光充足。保持土壤湿润。喜温暖，不耐寒。定期修剪促进开花。'),
-- 13. 天人菊
(13, 'blanket_flower', '天人菊', 'Gaillardia aristata', '菊科', 'Asteraceae', '天人菊属', 'Gaillardia', '喜阳光充足，耐热耐旱性强。适应性广，对土壤要求不严。', '天人菊是菊科天人菊属的多年生草本植物，常作一年生栽培。株高30-60厘米，茎直立，多分枝。叶片披针形或羽状分裂。头状花序单生茎顶，舌状花黄色或橙色，管状花红褐色，花大而鲜艳。花期6-10月。', '花朵大而鲜艳，黄橙色系。舌状花常有两种颜色。适应性强，耐旱。', '6-10月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐旱能力强。土壤要求不严。保持土壤微湿。及时摘除残花延长花期。'),
-- 14. 荷包牡丹
(14, 'bleeding_heart', '荷包牡丹', 'Lamprocapnos spectabilis', '罂粟科', 'Papaveraceae', '荷包牡丹属', 'Lamprocapnos', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '荷包牡丹是罂粟科荷包牡丹属的多年生草本植物。株高50-100厘米，茎直立。叶片羽状分裂，灰绿色。总状花序侧生，下垂，花朵心形，粉红色或白色，形似荷包，故名荷包牡丹。花期4-6月。', '花朵心形，下垂如荷包。叶片羽状分裂。春季开花。', '4-6月', '原产于中国东北、朝鲜、日本等地，现世界各地广泛栽培', '喜半阴环境，避免烈日暴晒。保持土壤湿润。耐寒，夏季休眠。定期分株更新。'),
-- 15. 金盏菊
(15, 'calendula', '金盏菊', 'Calendula officinalis', '菊科', 'Asteraceae', '金盏花属', 'Calendula', '喜阳光充足，耐寒性强。适应性广，喜凉爽气候，不耐高温。对土壤要求不严。', '金盏菊是菊科金盏花属的一年生或二年生草本植物。株高30-60厘米，全株被毛。叶片互生，长圆形至倒卵形。头状花序单生枝顶，花色鲜艳，有黄色、橙色等，花瓣多层，形似菊花。可食用和药用。', '花朵金黄色或橙黄色，花瓣层层叠叠。花期长。叶片有毛被。', '4-6月、9-11月', '原产于地中海沿岸，现世界各地广泛栽培', '喜光照充足，保持土壤湿润但不积水。定期施肥促进开花。及时摘除残花延长花期。'),
-- 16. 舞春花
(16, 'calibrachoa', '舞春花', 'Calibrachoa hybrida', '茄科', 'Solanaceae', '舞春花属', 'Calibrachoa', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '舞春花是茄科舞春花属的多年生草本植物，常作一年生栽培。株高20-30厘米，茎匍匐或下垂。叶片小而狭，卵形。花单生叶腋，花冠漏斗形，有红、粉、紫、黄、白等多种颜色，花瓣常有条纹或斑点。花期长，从春末可持续到秋季霜降。', '花色丰富，花瓣常有条纹或斑点。植株低矮匍匐。适应性强。', '5-10月', '原产于南美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜温暖，不耐寒。定期修剪促进分枝和开花。'),
-- 17. 马蹄莲
(17, 'calla_lily', '马蹄莲', 'Zantedeschia aethiopica', '天南星科', 'Araceae', '马蹄莲属', 'Zantedeschia', '喜温暖湿润环境，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的微酸性土壤。', '马蹄莲是天南星科马蹄莲属的多年生草本植物。株高50-100厘米，具根茎。叶片心形或箭头形，绿色，有白色斑点。肉穗花序圆柱形，黄色，周围有白色的佛焰苞，呈漏斗形，形似马蹄。花期2-5月，是重要的切花材料。', '佛焰苞白色，形似马蹄。肉穗花序黄色。叶片心形有斑点。', '2-5月', '原产于非洲南部，现世界各地广泛栽培', '喜半阴环境，保持较高湿度。喜温暖，不耐寒。保持土壤湿润。冬季注意保温。'),
-- 18. 山茶
(18, 'camellia', '山茶', 'Camellia japonica', '山茶科', 'Theaceae', '山茶属', 'Camellia', '喜凉爽湿润气候，喜酸性土壤。喜半阴，忌强光直射。喜温暖湿润环境，不耐高温。', '山茶是山茶科山茶属的灌木或小乔木。株高1-6米，枝条光滑。叶片椭圆形，革质，深绿色，有光泽。花单生或数朵簇生枝顶，花大，直径5-12厘米，有单瓣和重瓣，花色有红、粉、白等，部分品种有斑点或条纹。花期11月至翌年4月，是中国传统名花。', '花朵大而美丽，色彩丰富。叶片革质有光泽。花期在冬春季。', '11月-翌年4月', '原产于中国，现世界各地广泛栽培', '喜酸性土壤，喜半阴。保持土壤湿润但排水良好。喜凉爽气候，夏季需遮阴。定期修剪整形。'),
-- 19. 白屈菜
(19, 'candytuft', '白屈菜', 'Iberis amara', '十字花科', 'Brassicaceae', '屈曲花属', 'Iberis', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '白屈菜是十字花科屈曲花属的一年生或多年生草本植物。株高15-30厘米，茎直立，多分枝。叶片披针形或匙形，互生。总状花序顶生，花小而密集，有白色、粉色、紫色等，花瓣四片，呈十字形排列。花期5-7月。', '花小密集，呈十字形排列。植株低矮紧凑。适应性强。', '5-7月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。耐寒。及时摘除残花促进持续开花。'),
-- 20. 康乃馨
(20, 'carnation', '康乃馨', 'Dianthus caryophyllus', '石竹科', 'Caryophyllaceae', '石竹属', 'Dianthus', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '康乃馨是石竹科石竹属的多年生草本植物。株高30-70厘米，茎直立，有节。叶片线形或披针形，对生，粉绿色。花单生或数朵簇生枝顶，花大，直径可达10厘米，有单瓣和重瓣，花色丰富，有红、粉、白、黄、紫等及复色品种。花瓣边缘有齿状缺刻，具有香气。', '花瓣边缘有齿状缺刻，具有香气。叶片粉绿色对生。花色丰富。', '4-9月', '原产于地中海沿岸，现世界各地广泛栽培', '喜阳光充足，喜凉爽气候。保持土壤湿润但不积水。喜微碱性土壤。定期施肥以磷钾肥为主。'),
-- 21. 粉色康乃馨
(21, 'carnation_pink', '粉色康乃馨', 'Dianthus caryophyllus Pink', '石竹科', 'Caryophyllaceae', '石竹属', 'Dianthus', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '粉色康乃馨是康乃馨的一个粉色品种，具有康乃馨的所有特征。花朵大而美丽，重瓣或单瓣，粉红色调，从浅粉到深粉都有，花瓣边缘有齿状缺刻，具有淡淡香气。叶片粉绿色对生。', '花朵粉红色，花瓣边缘有齿缺。叶片粉绿。具有康乃馨的典型特征。', '4-9月', '原产于地中海沿岸，现世界各地广泛栽培', '与康乃馨相同。喜阳光充足，喜凉爽气候。保持土壤湿润但不积水。喜微碱性土壤。'),
-- 22. 鸡冠花
(22, 'celosia', '鸡冠花', 'Celosia argentea var. cristata', '苋科', 'Amaranthaceae', '青葙属', 'Celosia', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '鸡冠花是苋科青葙属的一年生草本植物。株高30-90厘米，茎直立，多分枝。叶片卵形或披针形，互生。顶生穗状花序扁平，肉质，皱褶似鸡冠，有红、紫、黄、橙等鲜艳色彩。花期7-10月。', '花序扁平皱褶似鸡冠，色彩鲜艳。茎直立。叶片卵形。', '7-10月', '原产于热带非洲和亚洲，现世界各地广泛栽培', '喜阳光充足，耐热。保持土壤湿润但不积水。喜温暖，不耐寒。喜疏松肥沃土壤。'),
-- 23. 菊花
(23, 'chrysanthemum', '菊花', 'Chrysanthemum morifolium', '菊科', 'Asteraceae', '菊属', 'Chrysanthemum', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '菊花是菊科菊属的多年生草本植物。株高30-150厘米，茎直立，多分枝。叶片卵形至披针形，边缘有缺刻或分裂。头状花序单生或数个生于枝顶，花大小和形状因品种而异，有平瓣、舌瓣、管瓣等，花色极为丰富，有红、黄、白、紫、橙、绿及复色品种。花期9-12月，是中国传统名花之一。', '花形多样，色彩极其丰富。花期在秋季。是中国十大名花之一。', '9-12月', '原产于中国，现世界各地广泛栽培', '喜凉爽气候，喜阳光充足。保持土壤湿润但不积水。喜疏松肥沃土壤。秋季控制光照可调整花期。'),
-- 24. 鸡冠花（同celosia）
(24, 'cockscomb', '鸡冠花', 'Celosia argentea var. cristata', '苋科', 'Amaranthaceae', '青葙属', 'Celosia', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '鸡冠花是苋科青葙属的一年生草本植物，与第22项相同。株高30-90厘米，茎直立。叶片卵形。顶生花序扁平肉质，皱褶似鸡冠，色彩鲜艳。', '花序似鸡冠，色彩鲜艳。茎直立。喜阳光充足。', '7-10月', '原产于热带地区，现世界各地广泛栽培', '喜阳光充足，耐热。保持土壤湿润。喜温暖，不耐寒。适应性强。'),
-- 25. 耧斗菜
(25, 'columbine', '耧斗菜', 'Aquilegia vulgaris', '毛茛科', 'Ranunculaceae', '耧斗菜属', 'Aquilegia', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '耧斗菜是毛茛科耧斗菜属的多年生草本植物。株高40-80厘米，茎直立，多分枝。叶片基生和茎生，2-3回三出复叶，小叶圆形或卵形。花单生或数朵生于枝顶，花形奇特，花瓣5枚，下部花瓣延长成距，形似漏斗或耧斗，花色有蓝、紫、粉、白等。', '花瓣有距，花形奇特。叶片为2-3回三出复叶。色彩清雅。', '5-7月', '原产于欧洲、亚洲、北美洲，中国各地有分布', '喜半阴环境，避免烈日暴晒。保持土壤湿润。耐寒，夏季休眠。种子自播能力强。'),
-- 26. 松果菊
(26, 'coneflower', '松果菊', 'Echinacea purpurea', '菊科', 'Asteraceae', '松果菊属', 'Echinacea', '喜阳光充足，耐寒耐旱。适应性广，对土壤要求不严。', '松果菊是菊科松果菊属的多年生草本植物。株高60-120厘米，茎直立，多分枝。叶片卵形或披针形，边缘有锯齿。头状花序顶生，舌状花紫红色或白色，下垂或平展，管状花突出呈球形，绿色或紫褐色，形似松果。', '管状花突出呈球形，似松果。舌状花紫红色或白色。适应性强。', '6-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐旱能力强。土壤要求不严。保持土壤微湿。及时摘除残花促进持续开花。'),
-- 27. 金鸡菊
(27, 'coreopsis', '金鸡菊', 'Coreopsis grandiflora', '菊科', 'Asteraceae', '金鸡菊属', 'Coreopsis', '喜阳光充足，耐热耐旱。适应性广，对土壤要求不严。', '金鸡菊是菊科金鸡菊属的多年生草本植物，常作一年生栽培。株高30-90厘米，茎直立，多分枝。叶片羽状分裂或全缘。头状花序单生或数个生于枝顶，舌状花金黄色或橙黄色，管状花深黄色，形似雏菊。花期6-10月。', '舌状花金黄色，管状花深黄色。适应性强，花期长。', '6-10月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐旱。土壤要求不严。保持土壤微湿。及时摘除残花延长花期。'),
-- 28. 秋英
(28, 'cosmos', '秋英', 'Cosmos bipinnatus', '菊科', 'Asteraceae', '秋英属', 'Cosmos', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '秋英是菊科秋英属的一年生草本植物。株高1-2米，茎直立，细长而光滑。叶片羽状细裂，线形或丝状。头状花序单生或数个生于细长花梗顶端，舌状花有粉、红、白等色，管状花黄色，花大而轻盈。花期6-10月。', '花大轻盈，色彩柔和。叶片羽状细裂。茎细长光滑。', '6-10月', '原产于墨西哥，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。土壤要求不严。保持土壤微湿。需支架防止倒伏。'),
-- 29. 番红花
(29, 'crocus', '番红花', 'Crocus sativus', '鸢尾科', 'Iridaceae', '番红花属', 'Crocus', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。球根需要冬季低温春化。', '番红花是鸢尾科番红花属的多年生球根草本植物。株高10-20厘米。叶片线形，基生，常在花后伸长。花单生或数朵生于球茎上，花冠漏斗形，花被片6枚，淡紫色或白色，喉部有黄色条纹。柱头红色，伸出花外，可作香料和染料。', '花被片淡紫色，喉部黄色。柱头红色伸出花外。球根植物，春季开花。', '3-4月', '原产于地中海沿岸，现世界各地广泛栽培', '秋季种植球根，需要充足阳光。球根需要冬季低温春化。花后让叶片自然枯萎以养球。'),
-- 30. 水仙
(30, 'daffodil', '水仙', 'Narcissus pseudonarcissus', '石蒜科', 'Amaryllidaceae', '水仙属', 'Narcissus', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。球根需要冬季低温春化。', '水仙是石蒜科水仙属的多年生球根草本植物。株高20-40厘米。叶片线形，扁平，粉绿色。花单生或数朵生于花葶顶端，花冠高脚碟状，副冠喇叭形，黄色或白色，芳香扑鼻。是中国传统名花之一。', '花冠高脚碟状，副冠喇叭形。叶片扁平线形。芳香扑鼻。', '1-3月', '原产于地中海沿岸，现世界各地广泛栽培', '秋季种植水养，保持适当水位。喜凉爽环境，避免高温。保证充足光照。花开后剪除花茎，养球。'),
-- 31. 大丽花
(31, 'dahlia', '大丽花', 'Dahlia pinnata', '菊科', 'Asteraceae', '大丽花属', 'Dahlia', '喜凉爽气候，不耐高温。喜阳光充足。要求疏松肥沃、排水良好的土壤。', '大丽花是菊科大丽花属的多年生草本植物，具块根。株高50-150厘米，茎直立，多分枝。叶片1-3回羽状复叶，小叶卵形。头状花序大，直径可达30厘米，有多种花形，如单瓣型、球形型、仙人掌型等，花色极为丰富，几乎涵盖所有颜色。', '花大色艳，品种繁多，花型多样。块根肉质。叶片羽状复叶。', '6-10月', '原产于墨西哥，现世界各地广泛栽培', '喜凉爽气候，不耐高温。喜阳光充足。保持土壤湿润但不积水。块根不耐寒，冬季需挖出贮藏。'),
-- 32. 雏菊
(32, 'daisy', '雏菊', 'Bellis perennis', '菊科', 'Asteraceae', '雏菊属', 'Bellis', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '雏菊是菊科雏菊属的多年生草本植物，常作二年生栽培。株高10-15厘米，茎短缩，叶基生呈莲座状，叶片倒卵形或匙形。头状花序单生花葶顶端，舌状花白色或粉红色，管状花黄色，形似菊花但较小，故名雏菊。', '头状花序形似小菊花。叶片基生呈莲座状。植株低矮紧凑。', '3-6月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜凉爽气候，耐寒。喜阳光充足，也能耐半阴。保持土壤湿润。及时摘除残花促进持续开花。'),
-- 33. 萱草
(33, 'daylily', '萱草', 'Hemerocallis fulva', '百合科', 'Liliaceae', '萱草属', 'Hemerocallis', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '萱草是百合科萱草属的多年生草本植物，具肉质根。株高60-100厘米，叶基生，线形或剑形。花葶从叶丛中抽出，圆锥花序顶生，花大，漏斗形，橙黄色或黄红色，花瓣6枚，常清晨开放，傍晚凋谢，仅开一日。', '花大漏斗形，仅开一日。叶片线形基生。适应性强。是中国传统母亲花。', '5-8月', '原产于中国、日本，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。土壤要求不严。保持土壤湿润。分株繁殖，3-4年分株一次。'),
-- 34. 飞燕草
(34, 'delphinium', '飞燕草', 'Delphinium grandiflorum', '毛茛科', 'Ranunculaceae', '飞燕草属', 'Delphinium', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '飞燕草是毛茛科飞燕草属的多年生草本植物，常作一年生栽培。株高30-120厘米，茎直立，多分枝。叶片掌状分裂。总状花序顶生，花大而密集，花冠不整齐，有距，形似飞燕，有蓝、紫、粉、白等色。花期5-8月。', '花形似飞燕，有距。色彩丰富。茎直立。总状花序密集。', '5-8月', '原产于欧洲南部、亚洲西部，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜凉爽气候，不耐高温。需支架防止倒伏。'),
-- 35. 石竹
(35, 'dianthus', '石竹', 'Dianthus chinensis', '石竹科', 'Caryophyllaceae', '石竹属', 'Dianthus', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '石竹是石竹科石竹属的多年生草本植物。株高30-50厘米，茎直立，有节。叶片线状披针形，对生，节膨大。花单生或数朵簇生枝顶，花瓣5枚，先端有齿裂，粉红色或白色，有香气。花期5-9月。', '花瓣先端有齿裂。茎有节膨大。叶片对生线状披针形。有香气。', '5-9月', '原产于中国、朝鲜，现世界各地广泛栽培', '喜阳光充足，喜凉爽气候。保持土壤湿润但不积水。喜微碱性土壤。及时摘除残花促进持续开花。'),
-- 36. 异果菊
(36, 'dimorphotheca', '异果菊', 'Dimorphotheca sinuata', '菊科', 'Asteraceae', '异果菊属', 'Dimorphotheca', '喜阳光充足，耐热耐旱。适应性广，对土壤要求不严。', '异果菊是菊科异果菊属的一年生草本植物。株高20-40厘米，茎匍匐或直立，多分枝。叶片披针形或羽状分裂。头状花序单生枝顶，舌状花有橙、黄、白等色，管状花暗紫色或黑色，花大而鲜艳。花期5-7月。', '舌状花鲜艳，管状花暗色形成对比。花大。适应性强。', '5-7月', '原产于南非，现世界各地广泛栽培', '喜阳光充足，耐旱。土壤要求不严。保持土壤微湿。傍晚或阴天花朵闭合。'),
-- 37. 紫锥花
(37, 'echinacea', '紫锥花', 'Echinacea purpurea', '菊科', 'Asteraceae', '松果菊属', 'Echinacea', '喜阳光充足，耐寒耐旱。适应性广，对土壤要求不严。', '紫锥花是菊科松果菊属的多年生草本植物。与第26项松果菊相同。株高60-120厘米，茎直立。叶片卵形。头状花序，舌状花紫红色，管状花突出呈球形。', '管状花突出呈球形，舌状花紫红色。适应性强。可入药。', '6-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐旱。土壤要求不严。保持土壤微湿。及时摘除残花。'),
-- 38. 勿忘草
(38, 'forget_me_not', '勿忘草', 'Myosotis sylvatica', '紫草科', 'Boraginaceae', '勿忘草属', 'Myosotis', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '勿忘草是紫草科勿忘草属的一年生或二年生草本植物。株高15-30厘米，茎直立或斜生，全株有毛。叶片椭圆形或披针形，互生。蝎尾状聚伞花序顶生，花小而密集，花冠蓝色，喉部有黄色鳞片，花中央有白色或黄色眼斑。花期4-6月。', '花冠蓝色，喉部有黄色鳞片。植株有毛。象征永恒的记忆和友谊。', '4-6月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。喜凉爽气候。种子自播能力强。'),
-- 39. 紫茉莉
(39, 'four_o_clock', '紫茉莉', 'Mirabilis jalapa', '紫茉莉科', 'Nyctaginaceae', '紫茉莉属', 'Mirabilis', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '紫茉莉是紫茉莉科紫茉莉属的多年生草本植物，常作一年生栽培。株高50-100厘米，茎直立，多分枝。叶片卵形或心形，对生。花数朵簇生枝腋，花冠漏斗形，有紫红、粉、白、黄及复色，傍晚开放，次日午前凋谢，故名紫茉莉。花期6-10月。', '傍晚开放，午前凋谢。花冠漏斗形。叶片卵形对生。', '6-10月', '原产于热带美洲，现世界各地广泛栽培', '喜温暖，不耐寒。喜阳光充足。土壤要求不严。保持土壤湿润。块根可越冬。'),
-- 40. 毛地黄
(40, 'foxglove', '毛地黄', 'Digitalis purpurea', '车前科', 'Plantaginaceae', '毛地黄属', 'Digitalis', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '毛地黄是车前科毛地黄属的二年生或多年生草本植物。株高60-120厘米，茎直立，全株被柔毛。叶片基生和茎生，卵形或椭圆形，边缘有齿。总状花序顶生，花冠钟形，下垂，有紫红、粉、白等色，内有斑点。花期5-7月。', '花冠钟形下垂，内有斑点。全株被柔毛。是重要的药用植物。', '5-7月', '原产于欧洲、亚洲西部，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。喜凉爽气候。注意：全株有毒，不可误食。'),
-- 41. 小苍兰
(41, 'freesia', '小苍兰', 'Freesia refracta', '鸢尾科', 'Iridaceae', '香雪兰属', 'Freesia', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。球根需要冬季低温春化。', '小苍兰是鸢尾科香雪兰属的多年生球根草本植物。株高30-50厘米，茎直立。叶片线形或剑形，基生。花茎细长，总状花序偏向一侧，花漏斗形，有白、黄、粉、红、紫等色，芳香浓郁。花期2-4月，是重要的切花材料。', '花漏斗形，芳香浓郁。花序偏向一侧。叶片线形。', '2-4月', '原产于南非，现世界各地广泛栽培', '秋季种植，春季开花。喜凉爽环境。保证充足光照。花开后剪除花茎，让叶片自然枯萎。'),
-- 42. 天人菊（同13）
(42, 'gaillardia', '天人菊', 'Gaillardia aristata', '菊科', 'Asteraceae', '天人菊属', 'Gaillardia', '喜阳光充足，耐热耐旱。适应性广，对土壤要求不严。', '天人菊是菊科天人菊属的多年生草本植物。与第13项相同。株高30-60厘米。叶片披针形。头状花序，舌状花黄色或橙色，管状花红褐色。', '花朵大而鲜艳，黄橙色系。适应性强，耐旱。', '6-10月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐旱。土壤要求不严。保持土壤微湿。及时摘除残花。'),
-- 43. 栀子
(43, 'gardenia', '栀子', 'Gardenia jasminoides', '茜草科', 'Rubiaceae', '栀子属', 'Gardenia', '喜温暖湿润气候，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的微酸性土壤。', '栀子是茜草科栀子属的灌木。株高1-3米，枝条丛生。叶片对生，椭圆形或卵状披针形，革质，深绿色，有光泽。花单生或数朵生于枝顶，花大，白色，漏斗形，浓郁芳香。花期5-7月。果实椭圆形，黄色，可作黄色染料。', '花大白色芳香。叶片革质有光泽。果实黄色可染色。是重要观赏和药用植物。', '5-7月', '原产于中国南方，现世界各地广泛栽培', '喜酸性土壤，喜半阴。保持土壤湿润。喜温暖，不耐寒。定期施肥以酸性肥料为主。'),
-- 44. 勋章菊
(44, 'gazania', '勋章菊', 'Gazania rigens', '菊科', 'Asteraceae', '勋章菊属', 'Gazania', '喜阳光充足，耐热耐旱。适应性广，对土壤要求不严。', '勋章菊是菊科勋章菊属的多年生草本植物，常作一年生栽培。株高20-30厘米，茎匍匐或直立。叶片基生，匙形或羽状分裂，灰绿色。头状花序单生茎顶，舌状花有黄、橙、白等色，基部有深色环带，形似勋章，故名勋章菊。花期5-10月。', '舌状花基部有深色环带，形似勋章。叶片灰绿色。花朵仅在阳光下开放。', '5-10月', '原产于南非，现世界各地广泛栽培', '喜阳光充足，阴天和傍晚花朵闭合。耐旱能力强。土壤要求不严。保持土壤微湿。'),
-- 45. 天竺葵
(45, 'geranium', '天竺葵', 'Pelargonium hortorum', '牻牛儿苗科', 'Geraniaceae', '天竺葵属', 'Pelargonium', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '天竺葵是牻牛儿苗科天竺葵属的多年生草本植物。株高30-60厘米，茎肉质，多汁。叶片圆形或肾形，边缘有波状浅裂，具特殊气味。伞形花序顶生，小花密集，有红、粉、白、紫等色，有单瓣和重瓣品种。花期几乎全年。', '叶片圆形有波状浅裂，具特殊气味。伞形花序，小花密集。适应性强。', '全年', '原产于南非，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜温暖，不耐寒。夏季注意通风降温。'),
-- 46. 非洲菊
(46, 'gerbera', '非洲菊', 'Gerbera jamesonii', '菊科', 'Asteraceae', '非洲菊属', 'Gerbera', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微酸性土壤。', '非洲菊是菊科非洲菊属的多年生草本植物。株高30-60厘米，具短缩茎。叶片基生，羽状分裂或深裂。头状花序单生花葶顶端，花极大，直径可达10厘米，舌状花有红、粉、橙、黄、白等色，管状花黄褐色。花期几乎全年，是重要的切花材料。', '花大色艳，色彩丰富。叶片基生羽状分裂。是重要切花。', '全年', '原产于南非，现世界各地广泛栽培', '喜温暖，不耐寒。喜阳光充足，也能耐半阴。保持土壤湿润但排水良好。喜微酸性土壤。'),
-- 47. 唐菖蒲
(47, 'gladiolus', '唐菖蒲', 'Gladiolus gandavensis', '鸢尾科', 'Iridaceae', '唐菖蒲属', 'Gladiolus', '喜凉爽气候，不耐高温。喜阳光充足。要求疏松肥沃、排水良好的土壤。球根需要冬季低温春化。', '唐菖蒲是鸢尾科唐菖蒲属的多年生球根草本植物。株高60-150厘米，茎直立。叶片剑形，基生或茎生，互相套叠。花茎从叶丛中抽出，穗状花序顶生，花大而美丽，有红、粉、黄、白、紫等色及复色品种，花冠漏斗形。花期6-10月，是世界著名切花。', '穗状花序顶生，花大美丽。叶片剑形。球根植物。重要切花。', '6-10月', '原产于地中海沿岸、非洲热带，现世界各地广泛栽培', '春季种植，夏季开花。喜阳光充足。保持土壤湿润但不积水。花开后剪除花茎，养球。'),
-- 48. 堆心菊
(48, 'helenium', '堆心菊', 'Helenium autumnale', '菊科', 'Asteraceae', '堆心菊属', 'Helenium', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '堆心菊是菊科堆心菊属的多年生草本植物。株高60-150厘米，茎直立，多分枝。叶片披针形或卵形，边缘有锯齿。头状花序圆锥状排列，舌状花黄色或橙色，管状花黄褐色或深褐色，花期8-10月。', '头状花序圆锥状排列，花期在秋季。适应性强。', '8-10月', '原产于北美洲，现世界各地广泛栽培', '喜凉爽气候，喜阳光充足。保持土壤湿润。耐寒。及时摘除残花促进持续开花。'),
-- 49. 向日葵
(49, 'helianthus', '向日葵', 'Helianthus annuus', '菊科', 'Asteraceae', '向日葵属', 'Helianthus', '喜温暖气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '向日葵是菊科向日葵属的一年生草本植物。株高1-3米，茎直立，粗壮。叶片大，心形或卵圆形，互生。头状花序极大，直径可达30厘米，边缘为舌状花，黄色，管状花棕色或紫褐色，花序随太阳转动，故名向日葵。种子可食。', '花序随太阳转动。头状花序极大，边缘舌状花黄色。种子可食用。', '7-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐热。土壤要求不严。保持土壤湿润。喜温暖，不耐寒。种子可食用。'),
-- 50. 赛菊芋
(50, 'heliopsis', '赛菊芋', 'Heliopsis helianthoides', '菊科', 'Asteraceae', '赛菊芋属', 'Heliopsis', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '赛菊芋是菊科赛菊芋属的多年生草本植物。株高60-150厘米，茎直立，多分枝。叶片卵形或三角形，边缘有锯齿。头状花序单生或数个生于枝顶，舌状花金黄色，管状花黄褐色，形似小型向日葵。花期6-9月。', '花形似向日葵但较小。舌状花金黄色。适应性强。', '6-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。耐寒。及时摘除残花促进持续开花。'),
-- 51. 木槿
(51, 'hibiscus', '木槿', 'Hibiscus syriacus', '锦葵科', 'Malvaceae', '木槿属', 'Hibiscus', '喜温暖湿润气候，耐寒性较强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '木槿是锦葵科木槿属的落叶灌木。株高2-4米，枝条细长。叶片菱形或卵形，边缘有缺刻或分裂。花单生或数朵簇生于叶腋，花大，钟形，有红、粉、白、紫等色，有的品种有条纹或斑点，单朵花期仅一日，但花量大，可持续开花数月。', '花大美丽，但单朵仅开一日。适应性强，花期长。', '7-10月', '原产于中国、印度，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。土壤要求不严。保持土壤湿润。定期修剪促进分枝和开花。'),
-- 52. 蜀葵
(52, 'hollyhock', '蜀葵', 'Alcea rosea', '锦葵科', 'Malvaceae', '蜀葵属', 'Alcea', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '蜀葵是锦葵科蜀葵属的二年生或多年生草本植物。株高1.5-3米，茎直立，少分枝。叶片大，心形或圆形，边缘有波状浅裂。花大，单生或数朵簇生于叶腋，花冠漏斗形，有红、粉、白、黄、紫等色及重瓣品种。花期6-8月。', '植株高大，花大色艳。叶片大心形。花期在夏季。适应性强。', '6-8月', '原产于中国，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。耐寒。需支架防止倒伏。种子自播能力强。'),
-- 53. 玉簪
(53, 'hosta', '玉簪', 'Hosta ventricosa', '天门冬科', 'Asparagaceae', '玉簪属', 'Hosta', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '玉簪是天门冬科玉簪属的多年生草本植物。株高30-60厘米，具根状茎。叶片基生，大型，心形或卵形，绿色或带有白色斑纹，质地柔软。花葶从叶丛中抽出，总状花序顶生，花大，白色，漏斗形，芳香，夜间开放。花期6-8月。', '叶片心形或卵形，常有白色斑纹。花白色漏斗形芳香。喜半阴环境。', '6-8月', '原产于中国、日本，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。耐寒。叶片美观，常作为观叶植物栽培。'),
-- 54. 风信子
(54, 'hyacinth', '风信子', 'Hyacinthus orientalis', '天门冬科', 'Asparagaceae', '风信子属', 'Hyacinthus', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。球根需要冬季低温春化。', '风信子是天门冬科风信子属的多年生球根草本植物。株高20-30厘米。叶片线形或带状，基生。花葶从叶丛中抽出，总状花序顶生，小花密集呈穗状，花冠钟形，有红、粉、蓝、白、黄等色，芳香浓郁。花期3-4月。', '小花密集呈穗状，芳香浓郁。色彩丰富。球根植物。', '3-4月', '原产于地中海沿岸，现世界各地广泛栽培', '秋季种植，春季开花。喜凉爽环境。保证充足光照。花开后剪除花茎，养球。'),
-- 55. 冰花
(55, 'ice_plant', '冰花', 'Dorotheanthus bellidiformis', '番杏科', 'Aizoaceae', '冰花属', 'Dorotheanthus', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热耐旱。要求疏松肥沃、排水良好的沙质土壤。', '冰花是番杏科冰花属的多年生草本植物，常作一年生栽培。株高10-15厘米，茎匍匐。叶片肉质，匙形或线形，表面有许多透明突起，在阳光下闪烁如冰晶。花单生枝顶，花大，有红、粉、白、黄等色，仅在阳光下开放。花期5-7月。', '叶片表面有透明突起如冰晶。花仅在阳光下开放。肉质植物。', '5-7月', '原产于南非，现世界各地广泛栽培', '喜阳光充足，阴天和傍晚花朵闭合。耐旱能力强。使用排水良好的沙质土壤。保持土壤微湿。'),
-- 56. 凤仙花（同9）
(56, 'impatiens', '凤仙花', 'Impatiens walleriana', '凤仙花科', 'Balsaminaceae', '凤仙花属', 'Impatiens', '喜温暖湿润气候，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '凤仙花是凤仙花科凤仙花属的多年生草本植物，常作一年生栽培。株高20-40厘米，茎肉质多汁，半透明。叶片卵形或椭圆形，边缘有锯齿。花单生或数朵簇生于叶腋，花冠蝶形，有红、粉、紫、白等色及复色品种，花形优美。花期5-10月。', '茎肉质半透明。花色丰富，花形优美。喜半阴环境。', '5-10月', '原产于非洲热带地区，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。喜温暖，不耐寒。注意通风，预防病害。'),
-- 57. 鸢尾
(57, 'iris', '鸢尾', 'Iris germanica', '鸢尾科', 'Iridaceae', '鸢尾属', 'Iris', '喜凉爽湿润气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '鸢尾是鸢尾科鸢尾属的多年生草本植物，具根状茎。株高30-80厘米。叶片剑形或线形，基生，扇形排列。花大而美丽，外轮花被片下垂，内轮花被片直立或拱形，有蓝紫、白、黄等色。花期4-5月。', '花大美丽，外轮花被片下垂如鸢尾。叶片剑形扇形排列。适应性强。', '4-5月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但排水良好。耐寒。定期分株更新。'),
-- 58. 茉莉
(58, 'jasmine', '茉莉', 'Jasminum sambac', '木犀科', 'Oleaceae', '茉莉属', 'Jasminum', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微酸性土壤。', '茉莉是木犀科茉莉属的常绿灌木。株高0.5-3米，枝条细长。叶片对生，卵形或椭圆形，革质。聚伞花序顶生或腋生，花白色，重瓣或单瓣，芳香浓郁，夜间香气更盛。花期5-11月，以夏季最盛。', '花白色芳香浓郁。叶片革质对生。是中国传统名花，重要的香花植物。', '5-11月', '原产于印度、阿拉伯地区，现中国南方广泛栽培', '喜温暖，不耐寒。喜阳光充足。保持土壤湿润。喜微酸性土壤。定期修剪促进开花。'),
-- 59. 马缨丹
(59, 'lantana', '马缨丹', 'Lantana camara', '马鞭草科', 'Verbenaceae', '马缨丹属', 'Lantana', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '马缨丹是马鞭草科马缨丹属的常绿灌木。株高1-2米，茎四棱形，有短毛。叶片对生，卵形，边缘有锯齿，揉搓有特殊气味。头状花序顶生或腋生，小花密集，花冠筒状，有红、黄、橙、粉等色，常一花序上有多种颜色。花期几乎全年。', '头状花序颜色丰富多变。叶片揉搓有气味。全株有毒。', '全年', '原产于热带美洲，现世界各地广泛栽培', '喜阳光充足，耐热。土壤要求不严。保持土壤湿润。注意：全株有毒，不可误食。定期修剪整形。'),
-- 60. 薰衣草
(60, 'lavender', '薰衣草', 'Lavandula angustifolia', '唇形科', 'Lamiaceae', '薰衣草属', 'Lavandula', '喜凉爽干燥气候，耐寒性强。喜阳光充足，忌积水。要求疏松肥沃、排水良好的微碱性土壤。', '薰衣草是唇形科薰衣草属的半灌木。株高30-100厘米，茎四棱形，多分枝。叶片线形或披针形，灰绿色，密被灰白色星状绒毛。轮伞花序顶生，花小而密集，花冠二唇形，蓝紫色，芳香浓郁。花期6-8月。', '花芳香浓郁，蓝紫色。叶片灰绿色有绒毛。重要的香精和药用植物。', '6-8月', '原产于地中海沿岸，现世界各地广泛栽培', '喜阳光充足，忌积水。喜凉爽气候。保持土壤干燥。喜微碱性土壤。定期修剪促进分枝。'),
-- 61. 蛇鞭菊
(61, 'liatris', '蛇鞭菊', 'Liatris spicata', '菊科', 'Asteraceae', '蛇鞭菊属', 'Liatris', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '蛇鞭菊是菊科蛇鞭菊属的多年生草本植物。株高60-150厘米，茎直立。叶片线形或披针形，基生或互生。穗状花序顶生，长可达30厘米，小花自上而下依次开放，形似响尾蛇的尾巴，故名蛇鞭菊，花紫红色或白色。花期7-9月。', '穗状花序细长，小花自上而下开放。形似蛇尾。色彩鲜艳。', '7-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。耐寒。需支架防止倒伏。'),
-- 62. 穗花蛇鞭菊
(62, 'liatris_spicata', '穗花蛇鞭菊', 'Liatris spicata', '菊科', 'Asteraceae', '蛇鞭菊属', 'Liatris', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '穗花蛇鞭菊是蛇鞭菊的一个品种，与第61项相同。株高60-150厘米，茎直立。叶片线形。穗状花序，小花自上而下开放，紫红色或白色。', '穗状花序细长，形似蛇尾。小花自上而下开放。适应性强。', '7-9月', '原产于北美洲，现世界各地广泛栽培', '与蛇鞭菊相同。喜阳光充足，也能耐半阴。保持土壤湿润。耐寒。'),
-- 63. 百合
(63, 'lily', '百合', 'Lilium brownii var. viridulum', '百合科', 'Liliaceae', '百合属', 'Lilium', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的微酸性土壤。球根需要冬季低温春化。', '百合是百合科百合属的多年生球根草本植物。株高50-150厘米，茎直立。叶片披针形或卵形，散生或轮生。花单生或数朵生于茎顶，花大而美丽，花冠漏斗形或钟形，有白、粉、黄、橙、红等色及复色品种，芳香浓郁。花期6-9月。', '花大芳香，色彩丰富。球根植物。是中国传统名花，象征纯洁和高雅。', '6-9月', '原产于中国，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润但排水良好。球根需要低温春化。花后剪除花茎，养球。'),
-- 64. 半边莲
(64, 'lobelia', '半边莲', 'Lobelia erinus', '桔梗科', 'Campanulaceae', '半边莲属', 'Lobelia', '喜凉爽湿润气候，不耐高温。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '半边莲是桔梗科半边莲属的一年生或多年生草本植物。株高10-30厘米，茎匍匐或直立，多分枝。叶片小而密，卵形或圆形。花单生叶腋或顶生，小花密集，花冠二唇形，下唇三裂平展如扇形，有蓝、紫、白、粉等色。花期5-9月。', '花冠下唇三裂平展如扇形。植株低矮紧凑。色彩丰富。', '5-9月', '原产于南非洲，现世界各地广泛栽培', '喜凉爽气候，不耐高温。喜阳光充足，也能耐半阴。保持土壤湿润。夏季注意遮阴降温。'),
-- 65. 荷花
(65, 'lotus', '荷花', 'Nelumbo nucifera', '莲科', 'Nelumbonaceae', '莲属', 'Nelumbo', '喜温暖湿润气候，不耐寒。喜阳光充足。要求在静水或流动缓慢的水中生长，泥土深厚肥沃。', '荷花是莲科莲属的多年生水生草本植物。根状茎肥厚，即莲藕。叶片大而圆，盾形，挺出水面，叶脉明显。花单生于花梗顶端，大而美丽，有红、粉、白等色，芳香浓郁。果实为莲蓬，内有莲子。花期6-9月，是中国传统名花之一。', '叶片大而圆盾形。花大美丽。根状茎（莲藕）和种子（莲子）可食用。象征纯洁。', '6-9月', '原产于中国，现世界各地广泛栽培', '需要充足阳光和充足生长空间。保持水位稳定。喜肥沃的塘泥。冬季可移入室内或加深水位防寒。'),
-- 66. 羽扇豆
(66, 'lupin', '羽扇豆', 'Lupinus polyphyllus', '豆科', 'Fabaceae', '羽扇豆属', 'Lupinus', '喜凉爽湿润气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微酸性土壤。', '羽扇豆是豆科羽扇豆属的多年生草本植物。株高50-150厘米，茎直立。掌状复叶，小叶7-15枚，长椭圆形。总状花序顶生，长可达50厘米，小花密集排列，有蓝、紫、粉、白、黄等色，形似豌豆花。花期5-7月。', '掌状复叶，小叶多枚。总状花序长而密集。色彩丰富。是重要的绿肥和饲料植物。', '5-7月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但排水良好。喜微酸性土壤。种子可食用，但需处理去除苦味。'),
-- 67. 玉兰
(67, 'magnolia', '玉兰', 'Magnolia denudata', '木兰科', 'Magnoliaceae', '木兰属', 'Magnolia', '喜凉爽湿润气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微酸性土壤。', '玉兰是木兰科木兰属的落叶乔木。株高可达15-25米，树皮灰色。叶片互生，倒卵形或椭圆状卵形，先端宽而短。花先叶开放，单生于枝顶，花大，直径12-15厘米，花被片9枚，白色至淡紫色，芳香浓郁。花期3-4月。', '花先叶开放，花大芳香。是中国传统名花，象征高洁。', '3-4月', '原产于中国中部，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但排水良好。喜微酸性土壤。耐寒。定期修剪整形。'),
-- 68. 万寿菊
(68, 'marigold', '万寿菊', 'Tagetes erecta', '菊科', 'Asteraceae', '万寿菊属', 'Tagetes', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '万寿菊是菊科万寿菊属的一年生草本植物。株高30-100厘米，茎直立，多分枝。叶片羽状分裂，边缘有锯齿。头状花序单生或数个生于枝顶，舌状花黄色或橙黄色，管状花黄色，花大而密集。花期6-10月。', '花黄色或橙黄色，密集。叶片羽状分裂。适应性强。花有特殊气味，可驱虫。', '6-10月', '原产于墨西哥，现世界各地广泛栽培', '喜阳光充足，耐热。土壤要求不严。保持土壤微湿。喜温暖，不耐寒。'),
-- 69. 美国薄荷
(69, 'monarda', '美国薄荷', 'Monarda didyma', '唇形科', 'Lamiaceae', '美国薄荷属', 'Monarda', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '美国薄荷是唇形科美国薄荷属的多年生草本植物。株高60-120厘米，茎直立，四棱形。叶片对生，卵形或卵状披针形，边缘有锯齿。轮伞花序顶生，小花密集，花冠二唇形，有红、粉、紫等色，芳香浓郁。花期7-9月。', '轮伞花序顶生，小花密集。叶片有薄荷香气。花色鲜艳。', '7-9月', '原产于北美洲，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。耐寒。叶片可泡茶或做菜。'),
-- 70. 牵牛花
(70, 'morning_glory', '牵牛花', 'Ipomoea nil', '旋花科', 'Convolvulaceae', '番薯属', 'Ipomoea', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '牵牛花是旋花科番薯属的一年生缠绕草本植物。茎蔓生，可达3-5米，左旋缠绕。叶片心形或三裂。花单生或数朵簇生于叶腋，花冠漏斗形，有蓝、紫、红、白等色，清晨开放，午后凋谢。花期6-10月。', '花清晨开放，午后凋谢。花冠漏斗形。茎蔓生缠绕。适应性强。', '6-10月', '原产于热带美洲，现世界各地广泛栽培', '需要支架供其缠绕。喜阳光充足。保持土壤湿润。喜温暖，不耐寒。种子自播能力强。'),
-- 71. 太阳花
(71, 'moss_rose', '太阳花', 'Portulaca grandiflora', '马齿苋科', 'Portulacaceae', '马齿苋属', 'Portulaca', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热耐旱。对土壤要求不严，适应性强。', '太阳花是马齿苋科马齿苋属的一年生肉质草本植物。株高10-30厘米，茎匍匐或斜生。叶片肉质，圆柱形或扁平。花单生或数朵簇生于枝顶，花大，直径可达5厘米，有红、粉、黄、白、橙等色及重瓣品种，仅在阳光下开放。花期6-10月。', '花仅在阳光下开放。叶片肉质。适应性强，耐旱。', '6-10月', '原产于南美洲，现世界各地广泛栽培', '喜阳光充足，阴天和傍晚花朵闭合。耐旱能力强。土壤要求不严。保持土壤微湿。'),
-- 72. 龙面花
(72, 'nemesia', '龙面花', 'Nemesia strumosa', '玄参科', 'Scrophulariaceae', '龙面花属', 'Nemesia', '喜凉爽湿润气候，不耐高温。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '龙面花是玄参科龙面花属的一年生草本植物。株高20-40厘米，茎直立，多分枝。叶片对生，卵形或披针形，边缘有锯齿。总状花序顶生，小花密集，花冠二唇形，上唇大而下唇小，有红、粉、黄、白等色，喉部常有黄色斑点。花期5-7月。', '花冠二唇形，形似龙面。色彩丰富。植株低矮紧凑。', '5-7月', '原产于南非，现世界各地广泛栽培', '喜凉爽气候，不耐高温。喜阳光充足，也能耐半阴。保持土壤湿润。夏季注意遮阴降温。'),
-- 73. 兰花
(73, 'orchid', '兰花', 'Cymbidium hybridum', '兰科', 'Orchidaceae', '兰属', 'Cymbidium', '喜温暖湿润环境，适宜温度15-28℃。喜半阴，忌强光直射。要求疏松透气、排水良好的基质，如树皮、水苔等。', '兰花是兰科兰属的多年生草本植物。叶片线形或带状，革质，绿色。总状花序顶生或腋生，花大而美丽，有红、粉、黄、白、绿及复色品种，花瓣和萼片相似，唇瓣明显，常有斑点或条纹，芳香扑鼻。花期因品种而异，可从冬末持续到春季。是中国传统名花之一，象征高洁。', '花形优美，芳香扑鼻。叶片线形革质。是中国传统名花，象征高洁典雅。', '冬末至春季', '原产于亚洲热带和亚热带地区，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持较高湿度和通风良好。使用疏松透气的基质。避免积水，薄肥勤施。'),
-- 74. 蓝雏菊
(74, 'osteospermum', '蓝雏菊', 'Osteospermum ecklonis', '菊科', 'Asteraceae', '蓝雏菊属', 'Osteospermum', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '蓝雏菊是菊科蓝雏菊属的多年生草本植物，常作一年生栽培。株高30-50厘米，茎直立，多分枝。叶片披针形或羽状分裂。头状花序单生枝顶，舌状花有蓝、紫、白、粉等色，管状花深蓝色或紫色，形似雏菊。花期5-10月。', '舌状花色彩丰富，管状花深蓝色。花形似雏菊。适应性强。', '5-10月', '原产于南非，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜凉爽气候。及时摘除残花延长花期。'),
-- 75. 三色堇
(75, 'pansy', '三色堇', 'Viola tricolor', '堇菜科', 'Violaceae', '堇菜属', 'Viola', '喜凉爽湿润气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '三色堇是堇菜科堇菜属的一年生或二年生草本植物。株高10-30厘米，茎短缩。叶片基生或茎生，卵形或心形，边缘有锯齿。花单生叶腋，花大，直径可达6厘米，花瓣5枚，通常有三种颜色，上花瓣多为紫、蓝等色，中花瓣白或黄，下花瓣有条纹或斑点。花期3-7月。', '花通常有三种颜色，形似猫脸。适应性强，花期长。', '3-7月', '原产于欧洲，现世界各地广泛栽培', '喜凉爽气候，耐寒。喜阳光充足，也能耐半阴。保持土壤湿润。及时摘除残花促进持续开花。'),
-- 76. 牡丹
(76, 'peony', '牡丹', 'Paeonia suffruticosa', '芍药科', 'Paeoniaceae', '芍药属', 'Paeonia', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '牡丹是芍药科芍药属的落叶灌木。株高1-2米，枝条粗壮。叶片大，2-3回羽状复叶，小叶卵形或卵状披针形。花单生枝顶，花大，直径可达20厘米，有单瓣和重瓣，花色极为丰富，有红、粉、白、黄、紫、绿、黑及复色品种，雍容华贵。花期4-5月，是中国传统名花之一，象征富贵。', '花大色艳，雍容华贵。叶片大而复杂。是中国国花，象征富贵吉祥。', '4-5月', '原产于中国，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但排水良好。喜微碱性土壤。耐寒。秋季落叶后修剪整形。'),
-- 77. 矮牵牛
(77, 'petunia', '矮牵牛', 'Petunia × hybrida', '茄科', 'Solanaceae', '碧冬茄属', 'Petunia', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '矮牵牛是茄科碧冬茄属的多年生草本植物，常作一年生栽培。株高20-50厘米，茎匍匐或直立，全株有粘毛。叶片对生，卵形或椭圆形。花单生叶腋或顶生，花大，漏斗形，有红、粉、紫、白、黄等色及复色品种，有的有条纹或斑点，有单瓣和重瓣。花期4-10月。', '花大色艳，色彩丰富。适应性强，花期长。', '4-10月', '原产于南美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜温暖，不耐寒。定期修剪促进分枝和开花。'),
-- 78. 福禄考
(78, 'phlox', '福禄考', 'Phlox paniculata', '花荵科', 'Polemoniaceae', '福禄考属', 'Phlox', '喜凉爽湿润气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '福禄考是花荵科福禄考属的多年生草本植物。株高50-120厘米，茎直立，多分枝。叶片对生，卵形或披针形。圆锥花序顶生，小花密集，花冠高脚碟形，有红、粉、紫、白等色，芳香。花期6-9月。', '圆锥花序，小花密集芳香。色彩丰富。适应性强。', '6-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。耐寒。及时摘除残花促进持续开花。需支架防止倒伏。'),
-- 79. 罂粟
(79, 'poppy', '罂粟', 'Papaver somniferum', '罂粟科', 'Papaveraceae', '罂粟属', 'Papaver', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强。', '罂粟是罂粟科罂粟属的一年生草本植物。株高30-100厘米，茎直立，全株有白粉。叶片大，椭圆形或卵形，边缘有缺刻或分裂。花单生茎顶，花大，直径可达10厘米，花瓣4枚，有红、粉、白、紫等色，基部常有黑斑。蒴果球形，内含细小种子。花期5-7月。', '花大美丽，但全株有毒。蒴果可提取鸦片。', '5-7月', '原产于地中海沿岸，现世界各地有栽培', '喜阳光充足，也能耐半阴。土壤要求不严。注意：全株有毒，需谨慎处理。种子自播能力强。'),
-- 80. 太阳花（同71）
(80, 'portulaca', '太阳花', 'Portulaca grandiflora', '马齿苋科', 'Portulacaceae', '马齿苋属', 'Portulaca', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热耐旱。对土壤要求不严，适应性强。', '太阳花是马齿苋科马齿苋属的一年生肉质草本植物。与第71项相同。株高10-30厘米，茎匍匐。叶片肉质圆柱形。花单生枝顶，花大，有红、粉、黄、白、橙等色，仅在阳光下开放。', '花仅在阳光下开放。叶片肉质。适应性强，耐旱。', '6-10月', '原产于南美洲，现世界各地广泛栽培', '喜阳光充足。耐旱能力强。土壤要求不严。保持土壤微湿。'),
-- 81. 报春花
(81, 'primrose', '报春花', 'Primula malacoides', '报春花科', 'Primulaceae', '报春花属', 'Primula', '喜凉爽湿润气候，不耐高温。喜半阴，忌强光直射。要求疏松肥沃、排水良好、富含腐殖质的土壤。', '报春花是报春花科报春花属的多年生草本植物，常作二年生栽培。株高20-40厘米，茎短缩。叶片基生，呈莲座状，卵形或椭圆形，边缘有锯齿。伞形花序从叶丛中抽出，小花密集，有红、粉、白、紫等色，喉部常有黄色环。花期2-5月，是重要的早春观赏花卉。', '花期早，是早春重要的观赏花卉。小花密集成伞形花序。', '2-5月', '原产于中国西南地区，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持环境湿润。喜凉爽气候，夏季休眠。喜富含腐殖质的土壤。'),
-- 82. 帝王花
(82, 'protea', '帝王花', 'Protea cynaroides', '山龙眼科', 'Proteaceae', '帝王花属', 'Protea', '喜温暖干燥气候，耐寒性较弱。喜阳光充足。要求排水良好的酸性土壤。', '帝王花是山龙眼科帝王花属的灌木状多年生植物。株高可达1-2米。叶片大，革质，椭圆形，深绿色，有光泽。花序巨大，直径可达30厘米，总苞片多轮排列，革质，有红、粉、白等色，形似帝王冠冕，故名帝王花。花期长，可从冬季持续到春季。', '花序巨大，形似帝王冠冕。叶片革质有光泽。南非国花。', '冬季至春季', '原产于南非，现世界各地广泛栽培', '需要充足阳光和良好排水。喜酸性土壤。耐旱能力强。避免积水。冬季注意保温。'),
-- 83. 花毛茛
(83, 'ranunculus', '花毛茛', 'Ranunculus asiaticus', '毛茛科', 'Ranunculaceae', '毛茛属', 'Ranunculus', '喜凉爽气候，耐寒性较强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。球根需要秋季种植。', '花毛茛是毛茛科毛茛属的多年生草本植物，具块根。株高30-50厘米，茎直立。叶片为2-3回三出复叶，小叶深裂。花单生或数朵生于茎顶，花大，直径可达8厘米，有单瓣和重瓣，花色丰富，有红、粉、黄、白、橙、紫等及复色品种，形似牡丹，故名波斯牡丹。花期4-5月。', '花形似牡丹，色彩丰富。块根肉质。叶片为三出复叶。', '4-5月', '原产于地中海沿岸、亚洲西南部，现世界各地广泛栽培', '秋季种植块根。喜凉爽气候，喜阳光充足。保持土壤湿润但排水良好。花开后剪除花茎，让叶片自然枯萎。'),
-- 84. 玫瑰
(84, 'rose', '玫瑰', 'Rosa rugosa', '蔷薇科', 'Rosaceae', '蔷薇属', 'Rosa', '喜阳光充足，耐寒耐旱。喜温暖气候，适宜生长温度15-25℃。要求疏松肥沃、排水良好的微酸性土壤。', '玫瑰是蔷薇科蔷薇属的落叶灌木。株高1-2米，枝条密生针刺和刚毛。羽状复叶，小叶5-9枚，椭圆形或椭圆状倒卵形，皱褶明显。花单生或数朵簇生，花色丰富，有红、粉、白、黄等，具有浓郁芳香。果实扁球形，红色。花期5-10月。是中国传统名花之一。', '茎上密生尖刺，花朵芳香浓郁。叶片皱褶明显。象征爱情。', '5-10月', '原产于中国，现世界各地广泛栽培', '需充足阳光，每天至少6小时光照。定期修剪促进分枝和开花。注意防治病虫害，特别是白粉病和蚜虫。'),
-- 85. 黑心菊
(85, 'rudbeckia', '黑心菊', 'Rudbeckia hirta', '菊科', 'Asteraceae', '黑心菊属', 'Rudbeckia', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '黑心菊是菊科黑心菊属的一年生或二年生草本植物。株高30-100厘米，茎直立，多分枝，全株有粗糙毛。叶片卵形或披针形，边缘有锯齿。头状花序单生或数个生于枝顶，舌状花金黄色，管状花暗褐色或黑色，圆锥形，突出如眼，故名黑心菊。花期6-10月。', '管状花暗褐色或黑色，突出如眼。舌状花金黄色。适应性强。', '6-10月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。耐寒。及时摘除残花促进持续开花。'),
-- 86. 鼠尾草
(86, 'salvia', '鼠尾草', 'Salvia splendens', '唇形科', 'Lamiaceae', '鼠尾草属', 'Salvia', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '鼠尾草是唇形科鼠尾草属的多年生草本植物，常作一年生栽培。株高30-80厘米，茎直立，四棱形。叶片对生，三角形或卵形，边缘有锯齿。轮伞花序排成总状，顶生，小花密集，花冠二唇形，红色或紫红色，萼片同色。花期5-10月。', '轮伞花序顶生，小花密集红色。茎四棱形。叶片对生。', '5-10月', '原产于巴西，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。喜温暖，不耐寒。定期摘心促进分枝和开花。'),
-- 87. 景天
(87, 'sedum', '景天', 'Sedum spectabile', '景天科', 'Crassulaceae', '景天属', 'Sedum', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强，耐旱。', '景天是景天科景天属的多年生草本植物。株高30-50厘米，茎直立，粗壮。叶片大，肉质，椭圆形或卵形，对生或轮生，灰绿色。伞房花序顶生，小花密集，星形，有红、粉、白等色。花期8-10月。', '叶片肉质肥厚。伞房花序，小花星形密集。适应性强，耐旱。', '8-10月', '原产于中国、朝鲜，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。耐旱能力强，浇水要见干见湿。土壤要求不严。冬季休眠。'),
-- 88. 金鱼草
(88, 'snapdragon', '金鱼草', 'Antirrhinum majus', '车前科', 'Plantaginaceae', '金鱼草属', 'Antirrhinum', '喜凉爽气候，不耐高温。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '金鱼草是车前科金鱼草属的一年生或二年生草本植物。株高30-90厘米，茎直立。叶片对生，卵状披针形。总状花序顶生，小花密集，花冠筒状，唇形，形似金鱼张口，有红、粉、黄、白、橙、紫等色及复色品种。花期5-10月。', '花形似金鱼张口，色彩鲜艳。茎直立。适应性强。', '5-10月', '原产于地中海地区，现世界各地广泛栽培', '喜阳光充足，夏季高温时需遮阴。保持土壤湿润。喜凉爽气候。及时摘除残花促进持续开花。'),
-- 89. 紫罗兰
(89, 'stock', '紫罗兰', 'Matthiola incana', '十字花科', 'Brassicaceae', '紫罗兰属', 'Matthiola', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '紫罗兰是十字花科紫罗兰属的一年生或二年生草本植物。株高30-70厘米，茎直立，全株有灰白色星状毛。叶片长圆形或倒披针形，互生。总状花序顶生，小花密集，花瓣4枚，呈十字形排列，有紫红、粉、白等色，芳香浓郁。花期4-6月。', '花瓣十字形排列，芳香浓郁。花色丰富。适应性强。', '4-6月', '原产于欧洲、亚洲西部，现世界各地广泛栽培', '喜凉爽气候，耐寒。喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜微碱性土壤。'),
-- 90. 向日葵（同49）
(90, 'sunflower', '向日葵', 'Helianthus annuus', '菊科', 'Asteraceae', '向日葵属', 'Helianthus', '喜温暖气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '向日葵是菊科向日葵属的一年生草本植物。与第49项相同。株高1-3米，茎直立粗壮。叶片心形。花序大，边缘舌状花黄色，管状花棕色或紫褐色。种子可食用。', '花序随太阳转动。种子可食用。适应性强。', '7-9月', '原产于北美洲，现世界各地广泛栽培', '喜阳光充足，耐热。土壤要求不严。保持土壤湿润。喜温暖，不耐寒。'),
-- 91. 香豌豆
(91, 'sweet_pea', '香豌豆', 'Lathyrus odoratus', '豆科', 'Fabaceae', '山黧豆属', 'Lathyrus', '喜冷凉气候，不耐高温。喜阳光充足，耐半阴。要求疏松肥沃、排水良好的土壤。生长期需充足水分。', '香豌豆是豆科山黧豆属的一年生或二年生攀援草本植物。茎蔓生，可达2米，具翅。羽状复叶，顶端有卷须。总状花序腋生，花2-4朵着生于花梗上部，花冠蝶形，有白、粉、红、紫、蓝等多种颜色，具有浓郁香气。花期5-8月。', '花朵具有浓郁的蝶形花冠，香气浓郁。茎蔓生有翅。', '5-8月', '原产于地中海地区，现世界各地广泛栽培', '需要支架供其攀援生长。喜凉爽气候，不耐高温。保持土壤湿润，避免干旱。定期施肥。及时摘除残花促进持续开花。'),
-- 92. 美国石竹
(92, 'sweet_william', '美国石竹', 'Dianthus barbatus', '石竹科', 'Caryophyllaceae', '石竹属', 'Dianthus', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的微碱性土壤。', '美国石竹是石竹科石竹属的多年生草本植物，常作二年生栽培。株高30-60厘米，茎直立，有节。叶片对生，披针形。伞房花序顶生，小花密集，花瓣5枚，先端有齿裂，有红、粉、白等色及复色品种，常有对比色环带。花期5-7月。', '伞房花序，小花密集。瓣先端有齿裂，常有对比色环带。', '5-7月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。喜微碱性土壤。及时摘除残花促进持续开花。'),
-- 93. 夏堇
(93, 'torenia', '夏堇', 'Torenia fournieri', '母草科', 'Linderniaceae', '夏堇属', 'Torenia', '喜温暖湿润气候，不耐寒。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '夏堇是母草科夏堇属的一年生草本植物。株高20-30厘米，茎四棱形，多分枝。叶片对生，卵形或三角形，边缘有锯齿。花单生叶腋或顶生，花冠漏斗形，唇形，有蓝、紫、白、粉等色，喉部常有黄色斑点。花期6-10月。', '花冠漏斗形唇形，喉部常有黄斑。植株低矮紧凑。喜半阴环境。', '6-10月', '原产于亚洲热带地区，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。喜温暖，不耐寒。定期摘心促进分枝。'),
-- 94. 郁金香
(94, 'tulip', '郁金香', 'Tulipa gesneriana', '百合科', 'Liliaceae', '郁金香属', 'Tulipa', '喜凉爽气候，耐寒性强。喜阳光充足，不耐高温。要求疏松肥沃、排水良好的沙质壤土。球根需要冬季低温春化。', '郁金香是百合科郁金香属的多年生球根草本植物。株高20-40厘米。叶片3-5枚，带状披针形，粉绿色。花单生茎顶，杯状或碗状，花色极为丰富，有红、黄、白、粉、紫、黑等及复色品种。花期3-5月，是世界著名球根花卉。', '花朵杯状或碗状，色彩鲜艳丰富。叶片粉绿色带状。地下具鳞茎。', '3-5月', '原产于地中海沿岸及中亚地区，现世界各地广泛栽培', '秋季种植球根，需要充足阳光。球根需要冬季低温春化。花后及时剪除花茎，让叶片自然枯萎以养球。夏季休眠期保持干燥。'),
-- 95. 马鞭草
(95, 'verbena', '马鞭草', 'Verbena × hybrida', '马鞭草科', 'Verbenaceae', '马鞭草属', 'Verbena', '喜温暖湿润气候，不耐寒。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '马鞭草是马鞭草科马鞭草属的多年生草本植物，常作一年生栽培。株高20-50厘米，茎四棱形，多分枝，全株有毛。叶片对生，卵形或长圆形，边缘有锯齿。伞形花序顶生或腋生，小花密集，花冠漏斗形，有红、粉、紫、白等色。花期5-10月。', '伞形花序，小花密集。色彩丰富。适应性强。', '5-10月', '原产于美洲热带地区，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润。喜温暖，不耐寒。定期摘心促进分枝和开花。'),
-- 96. 紫罗兰
(96, 'violet', '紫罗兰', 'Viola odorata', '堇菜科', 'Violaceae', '堇菜属', 'Viola', '喜凉爽湿润气候，耐寒性强。喜半阴，忌强光直射。要求疏松肥沃、排水良好的土壤。', '紫罗兰是堇菜科堇菜属的多年生草本植物。株高10-15厘米，茎短缩。叶片基生，心形或卵形，边缘有锯齿。花单生或数朵生于花葶，花小，芳香浓郁，有紫红、粉、白等色。花期2-4月。', '花小芳香，紫色为主。叶片基生心形。耐阴。', '2-4月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜半阴环境，避免强光直射。保持土壤湿润。耐寒。种子自播能力强。'),
-- 97. 桂竹香
(97, 'wallflower', '桂竹香', 'Erysimum cheiri', '十字花科', 'Brassicaceae', '糖芥属', 'Erysimum', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。要求疏松肥沃、排水良好的土壤。', '桂竹香是十字花科糖芥属的多年生草本植物，常作二年生栽培。株高30-70厘米，茎直立，多分枝。叶片披针形或线形，互生。总状花序顶生，小花密集，花瓣4枚，呈十字形排列，有金黄、橙黄、橙红等色，芳香。花期4-6月。', '花瓣金黄色，呈十字形排列，芳香。适应性强。', '4-6月', '原产于欧洲南部，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。保持土壤湿润但不积水。耐寒。及时摘除残花促进持续开花。'),
-- 98. 蓍草
(98, 'yarrow', '蓍草', 'Achillea millefolium', '菊科', 'Asteraceae', '蓍属', 'Achillea', '喜凉爽气候，耐寒性强。喜阳光充足，也能耐半阴。对土壤要求不严，适应性强，耐旱。', '蓍草是菊科蓍属的多年生草本植物。株高30-100厘米，茎直立。叶片1-3回羽状分裂，裂片细小，状如蕨类。头状花序多数，排成伞房状，小花白色、粉红色或红色，花序平展如盘。花期6-9月。', '叶片羽状分裂如蕨类。头状花序平展如盘。适应性强，耐旱。', '6-9月', '原产于欧洲、亚洲，现世界各地广泛栽培', '喜阳光充足，也能耐半阴。耐旱能力强。土壤要求不严。保持土壤微湿。及时摘除残花。'),
-- 99. 百日草
(99, 'zinnia', '百日草', 'Zinnia elegans', '菊科', 'Asteraceae', '百日草属', 'Zinnia', '喜温暖湿润气候，不耐寒。喜阳光充足，耐热性强。对土壤要求不严，适应性强。', '百日草是菊科百日草属的一年生草本植物。株高30-90厘米，茎直立，多分枝。叶片对生，卵形或椭圆形，边缘有锯齿。头状花序单生枝顶，花大，直径可达10厘米，有单瓣和重瓣，花色极为丰富，有红、粉、黄、橙、白、紫等及复色品种。花期6-10月。', '花大色艳，色彩极其丰富。花期长，可达百日。适应性强。', '6-10月', '原产于墨西哥，现世界各地广泛栽培', '喜阳光充足，耐热。土壤要求不严。保持土壤湿润。喜温暖，不耐寒。及时摘除残花延长花期。');

-- ============================================================
-- 5. 创建识别历史表 (recognition_history)
-- ============================================================
CREATE TABLE IF NOT EXISTS `recognition_history` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '记录ID',
  `user_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '用户ID',
  `flower_id` INT UNSIGNED NOT NULL COMMENT '花卉ID',
  `class_id` INT UNSIGNED NOT NULL COMMENT '模型类别ID',
  `confidence` DECIMAL(5,4) NOT NULL COMMENT '置信度(0-1)',
  `recognition_method` VARCHAR(50) NOT NULL COMMENT '识别方法: coze/local',
  `is_offline` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否离线识别: 0-否, 1-是',
  `image_url` VARCHAR(500) NOT NULL COMMENT '识别图片URL',
  `latitude` DECIMAL(10,7) DEFAULT NULL COMMENT '纬度',
  `longitude` DECIMAL(10,7) DEFAULT NULL COMMENT '经度',
  `location_detail` VARCHAR(200) DEFAULT NULL COMMENT '位置详情',
  `model_version` VARCHAR(50) DEFAULT NULL COMMENT '使用的模型版本',
  `top_k_results` JSON DEFAULT NULL COMMENT 'Top K预测结果(JSON格式)',
  `is_favorite` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否收藏: 0-否, 1-是',
  `notes` TEXT DEFAULT NULL COMMENT '用户备注',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_flower_id` (`flower_id`),
  KEY `idx_class_id` (`class_id`),
  KEY `idx_recognition_method` (`recognition_method`),
  KEY `idx_is_offline` (`is_offline`),
  KEY `idx_is_favorite` (`is_favorite`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_location` (`latitude`, `longitude`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='识别历史表';

-- ============================================================
-- 6. 创建用户收藏表 (user_collections)
-- ============================================================
CREATE TABLE IF NOT EXISTS `user_collections` (
  `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '收藏ID',
  `user_id` BIGINT UNSIGNED NOT NULL COMMENT '用户ID',
  `flower_id` INT UNSIGNED NOT NULL COMMENT '花卉ID',
  `history_id` BIGINT UNSIGNED DEFAULT NULL COMMENT '关联的历史记录ID',
  `notes` TEXT DEFAULT NULL COMMENT '收藏备注',
  `tags` VARCHAR(200) DEFAULT NULL COMMENT '标签(逗号分隔)',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_flower_history` (`user_id`, `flower_id`, `history_id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_flower_id` (`flower_id`),
  KEY `idx_history_id` (`history_id`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='用户收藏表';

-- ============================================================
-- 7. 创建模型版本表 (model_versions)
-- ============================================================
CREATE TABLE IF NOT EXISTS `model_versions` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '版本ID',
  `version_name` VARCHAR(50) NOT NULL COMMENT '版本号(如: v1.0, v2.0)',
  `model_type` VARCHAR(50) NOT NULL COMMENT '模型类型: resnet50/mobilenetv3',
  `model_file` VARCHAR(200) NOT NULL COMMENT '模型文件路径',
  `onnx_file` VARCHAR(200) NOT NULL COMMENT 'ONNX模型文件路径',
  `labels_file` VARCHAR(200) NOT NULL COMMENT '标签文件路径',
  `num_classes` INT UNSIGNED NOT NULL COMMENT '类别数量',
  `accuracy` DECIMAL(5,4) NOT NULL COMMENT '准确率(0-1)',
  `inference_time_ms` INT UNSIGNED DEFAULT NULL COMMENT '平均推理时间(毫秒)',
  `model_size_mb` DECIMAL(10,2) DEFAULT NULL COMMENT '模型大小(MB)',
  `training_epochs` INT UNSIGNED DEFAULT NULL COMMENT '训练轮数',
  `training_data_size` INT UNSIGNED DEFAULT NULL COMMENT '训练数据量',
  `is_active` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否激活使用: 0-否, 1-是',
  `is_public` TINYINT(1) NOT NULL DEFAULT 1 COMMENT '是否公开: 0-否, 1-是',
  `description` TEXT DEFAULT NULL COMMENT '模型描述',
  `created_by` VARCHAR(50) DEFAULT NULL COMMENT '创建者',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_version_name` (`version_name`),
  KEY `idx_model_type` (`model_type`),
  KEY `idx_is_active` (`is_active`),
  KEY `idx_created_at` (`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='模型版本表';

-- ============================================================
-- 8. 创建系统配置表 (system_config)
-- ============================================================
CREATE TABLE IF NOT EXISTS `system_config` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '配置ID',
  `config_key` VARCHAR(100) NOT NULL COMMENT '配置键',
  `config_value` TEXT NOT NULL COMMENT '配置值',
  `config_type` VARCHAR(20) DEFAULT 'string' COMMENT '配置类型: string/number/boolean/json',
  `description` VARCHAR(200) DEFAULT NULL COMMENT '配置描述',
  `is_public` TINYINT(1) NOT NULL DEFAULT 0 COMMENT '是否公开: 0-否, 1-是',
  `created_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',

  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_config_key` (`config_key`),
  KEY `idx_is_public` (`is_public`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='系统配置表';

