-- ============================================================
-- 11. 创建索引优化查询性能
-- ============================================================

-- 复合索引优化常用查询
CREATE INDEX `idx_history_user_created` ON `recognition_history` (`user_id`, `created_at` DESC);
CREATE INDEX `idx_history_flower_created` ON `recognition_history` (`flower_id`, `created_at` DESC);
CREATE INDEX `idx_history_offline_created` ON `recognition_history` (`is_offline`, `created_at` DESC);
CREATE INDEX `idx_collection_user_created` ON `user_collections` (`user_id`, `created_at` DESC);

-- ============================================================
-- 12. 创建视图方便查询
-- ============================================================

-- 识别统计视图
CREATE OR REPLACE VIEW `v_recognition_stats` AS
SELECT
  f.english_name,
  f.chinese_name,
  COUNT(h.id) AS recognition_count,
  AVG(h.confidence) AS avg_confidence,
  SUM(CASE WHEN h.is_offline = 1 THEN 1 ELSE 0 END) AS offline_count,
  SUM(CASE WHEN h.is_offline = 0 THEN 1 ELSE 0 END) AS online_count,
  MAX(h.created_at) AS last_recognized_at
FROM flowers f
LEFT JOIN recognition_history h ON f.id = h.flower_id
GROUP BY f.id, f.english_name, f.chinese_name;

